DROP TABLE IF EXISTS `province_city_area`;
CREATE TABLE `province_city_area` (
  `id` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '行政区划代码(主键)',
  `pid` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '父级行政区划代码(省级为0)',
  `type` tinyint unsigned NOT NULL COMMENT '级别: 1-省/直辖市, 2-地级市/州/直辖市区县, 3-区县',
  `name` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '简称',
  `full_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '全称',
  `short_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '极简简称',
  `pinyin` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '拼音全拼',
  `pinyin_initial` char(1) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '拼音首字母',
  `area_code` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '电话区号',
  `sort` int DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  KEY `idx_pid` (`pid`),
  KEY `idx_type` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='中国行政区划表(包含区县完整版)';

